uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 1D Hash for random values
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// 2D Hash for positions
vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// Distance to a line segment
float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Helper to draw a synapse connection
void addConnection(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float coreSharpness, float haloSharpness, float fade, vec3 baseCyan, vec3 pulseGold, inout vec3 layerColor) {
    vec2 offs2 = offs + dir;

    // Get position of the target neighbor node
    vec2 p2 = offs2 + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs2) * 6.28);
    float dConn = distance(p1, p2);

    // Only draw if nodes are close enough
    if(dConn < 1.5) {
        float dLine = distLine(f, p1, p2);

        // Firing Pulse Logic (Syncs with the node)
        float pulseTime = t * 10.0 + hash21(id + offs) * 20.0;
        float pulse = smoothstep(0.9, 1.0, sin(dConn * 6.0 - pulseTime));

        // Line Rendering with DoF Sharpness
        float lineTotal = exp(-dLine * coreSharpness) + exp(-dLine * haloSharpness) * 0.4;

        // Fade lines out organically based on length
        float connFade = smoothstep(1.5, 0.7, dConn);

        // Accumulate color
        layerColor += mix(baseCyan, pulseGold, pulse * 1.5) * lineTotal * connFade * fade * (0.5 + pulse * 2.0);
    }
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing & Parameters
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;
    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = (u_layers <= 0.0) ? 5.0 : u_layers;

    // --- Deep Volumetric Background ---
    vec3 bgCenter = vec3(0.0, 0.08, 0.15); // Deep Teal/Blue
    vec3 bgEdge = vec3(0.0, 0.01, 0.03);   // Near Black
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.5);

    // Color Palette Settings
    vec3 baseCyan = vec3(0.1, 0.6, 1.0);
    vec3 pulseGold = vec3(1.0, 0.6, 0.1); // Warm firing color

    // 3. Infinite Zoom & Depth of Field Layer Loop
    for(int i = 0; i < 5; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Z-depth calculates distance from camera.
        float z = fract(fi * 0.2 + t * 0.1); 

        // Fade layers in at the back (z=1) and out at the camera (z=0)
        float fade = smoothstep(0.0, 0.2, z) * smoothstep(1.0, 0.8, z);

        // Depth of Field Blur: sharpest at z = 0.5, blurry at 0.0 and 1.0
        float blur = smoothstep(0.0, 0.5, abs(z - 0.5)); 

        // Dynamic sharpness based on DoF
        float coreSharpness = mix(60.0, 10.0, blur);
        float haloSharpness = mix(15.0, 3.0, blur);

        // Scale space based on depth to create 3D zoom
        float size = mix(12.0, 0.5, z) * scaleBase;
        vec2 layerUV = uv * size;

        // Parallax rotation per layer
        layerUV *= rot(z * 0.5 + fi);

        // Grid setup for Voronoi-style placement
        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        vec3 layerColor = vec3(0.0);
        float layerNodes = 0.0;

        // Loop through the 3x3 local neighborhood
        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));

                // Position of the node in this specific cell
                vec2 p1 = offs + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs) * 6.28);

                // 1. Draw the Node (Cell Body)
                float dNode = length(f - p1);
                layerNodes += exp(-dNode * coreSharpness) + (exp(-dNode * haloSharpness) * 0.5);

                // 2. Draw Connections to neighbors (Forward looking only to prevent duplicate drawing)
                // This eliminates the square cutoffs completely because all nearby lines are evaluated.
                addConnection(f, p1, offs, vec2(1.0, 0.0), id, t, coreSharpness, haloSharpness, fade, baseCyan, pulseGold, layerColor); // Right
                addConnection(f, p1, offs, vec2(0.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCyan, pulseGold, layerColor); // Down
                addConnection(f, p1, offs, vec2(1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCyan, pulseGold, layerColor); // Down-Right
                addConnection(f, p1, offs, vec2(-1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCyan, pulseGold, layerColor); // Down-Left
            }
        }

        // Add nodes to the layer using a bright white/cyan mix
        layerColor += mix(baseCyan, vec3(1.0), 0.7) * layerNodes * fade;

        // Apply hue shift uniform
        float hueShift = u_color_cycle * 3.14;
        layerColor.rg *= rot(hueShift);

        finalColor += layerColor * brightness;
    }

    // 4. Post-Processing
    float vig = 1.0 - length(uv0) * 0.7;
    finalColor *= smoothstep(0.0, 1.0, vig);

    // Tone mapping to prevent burning out the bright spots
    finalColor = finalColor / (1.0 + finalColor * 0.2);
    finalColor = pow(finalColor, vec3(0.85));

    fragColor = vec4(finalColor, 1.0);
}
